@startuml
class Faculty {
  +name : string
}
class Institute {
  +name : string
  +address : string
}
class Employee {
  +socialSecurityNumber : string
  +name : string
  +emailAddress : string
}
class ResearchStaff extends Employee {
  +fieldOfResearch : string
}
class AdministrativeStaff extends Employee {}
class ResearchAssistant extends ResearchStaff {
  +fieldOfResearch : string
}
class Lecturer extends ResearchAssistant {}
class Course {
  +id : int
  +name : string
  +weeklyDuration : int
}
class Project {
  +name : string
  +startDate : date
  +endDate : date
  +hours : int
}

Faculty "1" *-- "1..*" Institute
Faculty "1" -- "1" Employee : headed by dean
Institute "1" -- "*" ResearchAssistant : assigned to
ResearchAssistant "1" -- "*" Project : involved in
Lecturer "1" -- "*" Course : teaches
@enduml

